import { forwardRef, useCallback, useMemo, useRef, useState } from 'react';
import type { ListGroup } from '@arvo/core';
import ArvoActionMenu from '../ActionMenu/ActionMenu';
import type { MenuItemData } from '../ActionMenu/ActionMenu';
import { useControllableState } from '../../hooks/useControllableState';
import type { MenuSearchProp } from '../../types/menu-search';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface ArvoSplitButtonProps
  extends Omit<
    React.ButtonHTMLAttributes<HTMLButtonElement>,
    'disabled' | 'type' | 'onSelect' | 'defaultValue' | 'value'
  > {
  label: string;
  variant?: 'primary' | 'secondary' | 'tertiary';
  size?: 'sm' | 'md' | 'lg';
  icon?: string;
  mode?: 'action' | 'selection';
  displaySelected?: 'label' | 'value';
  value?: string | number | null;
  defaultValue?: string | number | null;
  isDisabled?: boolean;
  isActionDisabled?: boolean;
  isTriggerDisabled?: boolean;
  isLoading?: boolean;
  items: MenuItemData[] | ListGroup<MenuItemData>[];
  /** Enable search with defaults (`true`) or pass a config object. */
  search?: MenuSearchProp;
  placement?: 'top-start' | 'top-end' | 'bottom-start' | 'bottom-end';
  maxHeight?: string;
  hasGroupDividers?: boolean;
  closeOnSelect?: boolean;
  /**
   * Accessible name for the trigger (caret) segment, exposed via aria-label.
   * Default: "Show options".
   */
  triggerLabel?: string;
  onAction?: (
    event: React.MouseEvent<HTMLButtonElement>,
    selectedItem: MenuItemData | null,
  ) => void;
  onSelect?: (item: MenuItemData, index: number) => boolean | void;
  onOpen?: () => boolean | void;
  onClose?: () => boolean | void;
  onOpenChange?: (isOpen: boolean) => void;
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function isGrouped(
  items: MenuItemData[] | ListGroup<MenuItemData>[],
): items is ListGroup<MenuItemData>[] {
  return items.length > 0 && 'items' in items[0];
}

function flattenItems(
  items: MenuItemData[] | ListGroup<MenuItemData>[],
): MenuItemData[] {
  if (isGrouped(items)) return items.flatMap((g) => g.items);
  return items as MenuItemData[];
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

const ArvoSplitButton = forwardRef<HTMLButtonElement, ArvoSplitButtonProps>(
  function ArvoSplitButton(
    {
      label,
      variant = 'primary',
      size = 'md',
      icon,
      mode = 'action',
      displaySelected = 'label',
      value,
      defaultValue = null,
      isDisabled = false,
      isActionDisabled = false,
      isTriggerDisabled = false,
      isLoading = false,
      items,
      search,
      placement = 'bottom-end',
      maxHeight,
      hasGroupDividers = true,
      closeOnSelect = true,
      triggerLabel = 'Show options',
      className,
      onAction,
      onSelect,
      onOpen,
      onClose,
      onOpenChange,
      onClick,
      onFocus,
      onBlur,
      onKeyDown,
      ...rest
    },
    ref,
  ) {
    const wrapperRef = useRef<HTMLDivElement | null>(null);
    const actionRef = useRef<HTMLButtonElement | null>(null);
    const triggerRef = useRef<HTMLButtonElement | null>(null);

    // Menu size derived from the trigger size to keep menu config off the
    // trigger surface.
    const menuSize: 'sm' | 'md' = size === 'sm' ? 'sm' : 'md';

    // -- Open state (drives wrapper .open class for caret rotation) -------
    const [isOpen, setIsOpen] = useState(false);

    // -- Selection state --------------------------------------------------
    const [effectiveSelectedId, setSelectedId] = useControllableState<
      string | number | null
    >(value, defaultValue ?? null);

    const flat = useMemo(() => flattenItems(items), [items]);

    const selectedItem = useMemo(() => {
      if (effectiveSelectedId == null) return null;
      const id = String(effectiveSelectedId);
      return flat.find((item) => item.id === id) ?? null;
    }, [flat, effectiveSelectedId]);

    const displayLabel = useMemo(() => {
      if (mode === 'action' || !selectedItem) return label;
      if (displaySelected === 'value') {
        const val = (selectedItem as unknown as Record<string, unknown>).value;
        return val != null ? String(val) : selectedItem.id;
      }
      return selectedItem.label;
    }, [mode, selectedItem, label, displaySelected]);

    const displayIcon = useMemo(() => {
      if (mode === 'action') return icon;
      return selectedItem?.icon ?? icon;
    }, [mode, selectedItem, icon]);

    const processedItems = useMemo(() => {
      if (mode !== 'selection' || effectiveSelectedId == null) return items;

      const selId = String(effectiveSelectedId);
      const mark = (item: MenuItemData): MenuItemData => ({
        ...item,
        active: item.id === selId,
      });

      if (isGrouped(items)) {
        return items.map((group) => ({
          ...group,
          items: group.items.map(mark),
        }));
      }
      return (items as MenuItemData[]).map(mark);
    }, [items, mode, effectiveSelectedId]);

    // -- Custom event dispatch (always on the wrapper) --------------------
    const dispatchWrapperEvent = useCallback(
      (name: string, detail: unknown, cancelable = true) => {
        wrapperRef.current?.dispatchEvent(
          new CustomEvent(name, { bubbles: true, cancelable, detail }),
        );
      },
      [],
    );

    // -- Open / close pipeline (from internal ActionMenu) -----------------
    const handleOpenChange = useCallback(
      (next: boolean) => {
        setIsOpen(next);
        if (next) {
          dispatchWrapperEvent('split-btn:open', {});
        } else {
          dispatchWrapperEvent('split-btn:close', {});
        }
        onOpenChange?.(next);
      },
      [dispatchWrapperEvent, onOpenChange],
    );

    // -- Menu item selection ----------------------------------------------
    const handleMenuSelect = useCallback(
      (item: MenuItemData, index: number) => {
        if (mode === 'selection') {
          const previousItem = selectedItem;
          setSelectedId(item.id);
          dispatchWrapperEvent(
            'split-btn:change',
            { item, previousItem },
            false,
          );
        } else {
          dispatchWrapperEvent('split-btn:select', { item, index });
        }
        return onSelect?.(item, index);
      },
      [mode, selectedItem, setSelectedId, dispatchWrapperEvent, onSelect],
    );

    // -- Disabled flags per segment ---------------------------------------
    const actionDisabled = isDisabled || isActionDisabled || isLoading;
    const triggerDisabled = isDisabled || isTriggerDisabled || isLoading;

    // -- Action segment click ---------------------------------------------
    const handleActionClick = useCallback(
      (event: React.MouseEvent<HTMLButtonElement>) => {
        if (actionDisabled) return;

        if (mode === 'selection' && selectedItem) {
          const currentIndex = flat.findIndex((i) => i.id === selectedItem.id);
          dispatchWrapperEvent('split-btn:action', { selectedItem });
          onSelect?.(selectedItem, currentIndex);
        } else {
          dispatchWrapperEvent('split-btn:action', { selectedItem: null });
          onAction?.(event, null);
        }

        onClick?.(event);
      },
      [
        actionDisabled,
        mode,
        selectedItem,
        flat,
        dispatchWrapperEvent,
        onAction,
        onSelect,
        onClick,
      ],
    );

    // -- Keyboard on the action segment -----------------------------------
    // ArrowDown and Alt+ArrowDown both open the menu without first tabbing
    // to the caret trigger. Programmatic click on the trigger reuses
    // ArvoActionMenu's open + focus-trap flow.
    const handleActionKeyDown = useCallback(
      (event: React.KeyboardEvent<HTMLButtonElement>) => {
        onKeyDown?.(event);
        if (event.defaultPrevented) return;
        if (
          (event.key === 'ArrowDown' || (event.altKey && event.key === 'ArrowDown')) &&
          !actionDisabled
        ) {
          event.preventDefault();
          triggerRef.current?.click();
        }
      },
      [actionDisabled, onKeyDown],
    );

    // -- Forwarded + internal action ref merge ----------------------------
    const mergeActionRef = useCallback(
      (node: HTMLButtonElement | null) => {
        actionRef.current = node;
        if (typeof ref === 'function') {
          ref(node);
        } else if (ref) {
          (ref as React.MutableRefObject<HTMLButtonElement | null>).current =
            node;
        }
      },
      [ref],
    );

    // -- Class composition ------------------------------------------------
    const wrapperClasses = [
      'arvo-split-btn',
      `arvo-split-btn--${variant}`,
      `arvo-split-btn--${size}`,
      isOpen && 'open',
      isLoading && 'loading',
      className,
    ]
      .filter(Boolean)
      .join(' ');

    const segmentBaseClasses = [
      'arvo-btn',
      `arvo-btn--${variant}`,
      `arvo-btn--${size}`,
    ].join(' ');

    // -- Trigger element (cloned by ArvoActionMenu) -----------------------
    // The caret button is an internal segment of the SplitButton. It does
    // not expose a focus/blur contract -- consumers attach onFocus/onBlur
    // to the action segment instead.
    const triggerElement = (
      <button
        ref={triggerRef}
        type="button"
        className={`${segmentBaseClasses} arvo-split-btn__trigger`}
        disabled={triggerDisabled}
        aria-label={triggerLabel}
      >
        <span
          className="arvo-split-btn__caret o9con o9con-angle-down"
          aria-hidden="true"
        />
      </button>
    );

    return (
      <div
        ref={wrapperRef}
        className={wrapperClasses}
        role="group"
        aria-disabled={isDisabled || undefined}
        aria-busy={isLoading || undefined}
      >
        <button
          {...rest}
          ref={mergeActionRef}
          type="button"
          className={`${segmentBaseClasses} arvo-split-btn__action`}
          disabled={actionDisabled}
          onClick={handleActionClick}
          onKeyDown={handleActionKeyDown}
          onFocus={onFocus}
          onBlur={onBlur}
        >
          {displayIcon && (
            <span
              className={`arvo-split-btn__icon o9con o9con-${displayIcon}`}
              aria-hidden="true"
            />
          )}
          <span className="arvo-split-btn__lbl">{displayLabel}</span>
        </button>
        <ArvoActionMenu
          trigger={triggerElement}
          items={processedItems}
          size={menuSize}
          placement={placement}
          search={search}
          maxHeight={maxHeight}
          hasGroupDividers={hasGroupDividers}
          closeOnSelect={closeOnSelect}
          isDisabled={isDisabled || isTriggerDisabled || isLoading}
          isLoading={false}
          onOpen={onOpen}
          onClose={onClose}
          onSelect={handleMenuSelect}
          onOpenChange={handleOpenChange}
        />
      </div>
    );
  },
);

export default ArvoSplitButton;
export { ArvoSplitButton };
